#!/usr/bin/env Rscript
# SuSiE fine-mapping runner for BDB-Genomics.
#
# Inputs (all must be REAL, source-documented data):
#   1. Regional summary statistics TSV with columns:
#      rsid, chrom, pos_grch38, ref_allele, alt_allele, beta, se, n
#      (one row per variant; effect aligned to alt_allele)
#   2. Square LD matrix CSV (variant x variant, r2 values, header=row names)
#      generated by scripts/fetch_ld_ensembl.py --matrix-for ...
#   3. Sample size of the GWAS study (for susie_suff_stat); LD panel size is
#      recorded for documentation but SuSiE uses the GWAS sample size.
#
# Output: PIP table + 95% credible sets under results/finemapping/<locus>/
# This script refuses to run on placeholder inputs: every variant in the LD
# matrix must match the summary stats, and allele checks are enforced.

suppressPackageStartupMessages({
  library(data.table)
})

args <- commandArgs(trailingOnly = TRUE)
if (length(args) != 4) {
  stop("Usage: run_susie_finemap.R <sumstats.tsv> <ld_matrix.csv> <gwas_n> <output_dir>")
}
sumstats_path <- args[[1]]
ld_path <- args[[2]]
gwas_n <- as.integer(args[[3]])
out_dir <- args[[4]]

if (!requireNamespace("susieR", quietly = TRUE)) {
  stop("susieR not installed. Install with: conda install -c conda-forge r-susieR\n",
       "(or remotes::install_github('stephenslab/susieR'))")
}
library(susieR)

dir.create(out_dir, recursive = TRUE, showWarnings = FALSE)

sumstats <- fread(sumstats_path)
required <- c("rsid", "chrom", "pos_grch38", "ref_allele", "alt_allele", "beta", "se", "n")
missing <- setdiff(required, names(sumstats))
if (length(missing)) stop("Summary stats missing columns: ", paste(missing, collapse = ", "))
if (anyNA(sumstats$beta) || anyNA(sumstats$se)) stop("NA beta/se values present")

ld <- fread(ld_path)
ld_mat <- as.matrix(ld[, -1])
rownames(ld_mat) <- ld[[1]]
ld_mat <- ld_mat[order(rownames(ld_mat)), order(colnames(ld_mat))]

# --- Harmonization gates -----------------------------------------------------
common <- intersect(sumstats$rsid, rownames(ld_mat))
cat(sprintf("Sumstats: %d variants | LD matrix: %d | Matched: %d\n",
            nrow(sumstats), nrow(ld_mat), length(common)))
if (length(common) < 50) {
  stop("Fewer than 50 matched variants - refusing to fine-map a fragment.")
}
dropped <- setdiff(sumstats$rsid, common)
if (length(dropped)) {
  cat("Dropping (not in LD ref):", paste(head(dropped, 10), collapse = ", "),
      if (length(dropped) > 10) "...", "\n")
  fwrite(data.table(rsid = dropped, reason = "absent_from_LD_reference"),
         file.path(out_dir, "dropped_variants.tsv"))
}

ss <- sumstats[match(common, rsid)]
ld_mat <- ld_mat[common, common]

# Allele sanity vs LD sign convention is not verifiable from r2 alone; record
# alleles so downstream users can flip-check against their own reference.
fwrite(ss[, .(rsid, chrom, pos_grch38, ref_allele, alt_allele)],
       file.path(out_dir, "analyzed_variants.tsv"))

z <- ss$beta / ss$se

L_value <- min(10, floor(length(common) / 10))
fit <- susie_suff_stat(
  bhat = ss$beta,
  shat = ss$se,
  R = ld_mat,
  n = gwas_n,
  L = L_value,
  estimate_residual_variance = FALSE
)

pip <- as.numeric(susie_get_pip(fit))
res <- data.table(
  rsid = common,
  chrom = ss$chrom,
  pos_grch38 = ss$pos_grch38,
  ref_allele = ss$ref_allele,
  alt_allele = ss$alt_allele,
  pip = round(pip, 6),
  cs95 = NA_integer_
)
for (cs_idx in seq_along(fit$sets$cs)) {
  res[fit$sets$cs[[cs_idx]], cs95 := cs_idx]
}

fwrite(res[order(-pip)], file.path(out_dir, "susie_pips.tsv"))
if (!is.null(fit$sets$cs)) {
  cs_out <- lapply(names(fit$sets$cs), function(nm) {
    data.table(credible_set = nm,
               coverage = fit$sets$coverage[nm],
               variants = length(fit$sets$cs[[nm]]),
               lead_rsID = res$rsid[fit$sets$cs[[nm]]][which.max(res$pip[fit$sets$cs[[nm]]])])
  })
  fwrite(rbindlist(cs_out), file.path(out_dir, "credible_sets_95.tsv"))
} else {
  cat("No 95% credible sets found.\n")
}

readme <- sprintf(
  "# SuSiE fine-mapping (%s)

Run UTC: %s
Method: susie_suff_stat (susieR %s), L=%d, coverage=0.95
Input summary stats: %s (n=%d variants used, GWAS n=%d)
LD reference: %s (%d x %d, population documented by generator script)

Notes:
- PIPs and credible sets derive strictly from the two input files above.
- Allele alignment recorded in analyzed_variants.tsv for independent checking.
- No values in this directory are estimated outside SuSiE.
",
  basename(out_dir),
  format(Sys.time(), tz = "UTC"),
  as.character(packageVersion("susieR")),
  L_value,
  sumstats_path, nrow(res), gwas_n, ld_path, nrow(ld_mat), ncol(ld_mat)
)
writeLines(readme, file.path(out_dir, "README.md"))
cat("Done. Outputs in", out_dir, "\n")
